const $=id=>document.getElementById(id);for(let i=0;i<16;i++)$('motion').add(new Option(`Evaluation motion ${i+1}`,i));
Object.keys(DATA.prob).forEach(k=>$('model').add(new Option(k,k)));$('model').value='transformer-501';
let selected=0,playing=false,busy=false;
function state(){const m=+$('motion').value,raw=DATA.prob[$('model').value][m],z=raw.reduce((s,p,j)=>s+p*(DATA.gap[m][j]>=.02),0);const q=$('mode').value==='raw'?raw:raw.map((p,j)=>z>0?p*(DATA.gap[m][j]>=.02)/z:0);return{m,q,z};}
function obstacle(){const[x,y,z,k]=DATA.spec[selected];if(k===2){const xx=[],yy=[],zz=[],ii=[],jj=[],kk=[];for(let a=0;a<=10;a++)for(let b=0;b<16;b++){const th=Math.PI*a/10,ph=2*Math.PI*b/16;xx.push(x+.3*Math.sin(th)*Math.cos(ph));yy.push(y+.3*Math.sin(th)*Math.sin(ph));zz.push(z+.3*Math.cos(th));}for(let a=0;a<10;a++)for(let b=0;b<16;b++){let u=a*16+b,v=a*16+(b+1)%16;ii.push(u,v);jj.push(v,v+16);kk.push(u+16,u+16);}return{type:'mesh3d',x:xx,y:yy,z:zz,i:ii,j:jj,k:kk,color:'#f4ba5b',opacity:.7,hoverinfo:'skip'};}
const half=k===0?[.15,.8,.1]:[.3,.3,.4],xx=[],yy=[],zz=[];for(const a of [-1,1])for(const b of [-1,1])for(const c of [-1,1]){xx.push(x+a*half[0]);yy.push(y+b*half[1]);zz.push(z+c*half[2]);}return{type:'mesh3d',x:xx,y:yy,z:zz,i:[0,0,4,4,0,0,2,2,0,0,1,1],j:[1,3,6,7,4,5,3,7,2,6,5,7],k:[3,2,7,5,5,1,7,6,6,4,7,3],color:'#f4ba5b',opacity:.6,hoverinfo:'skip'};}
async function draw(){if(busy)return;busy=true;try{const{m,q,z}=state(),kind=+$('kind').value,points=DATA.motion[m][+$('frame').value],ids=DATA.spec.map((s,j)=>j).filter(j=>DATA.spec[j][3]===kind),near=q.reduce((a,p,j)=>a+p*(DATA.gap[m][j]>=.02&&DATA.gap[m][j]<=.12),0),hit=q.reduce((a,p,j)=>a+p*(DATA.gap[m][j]<0),0),mass=q.reduce((a,p,j)=>a+p*(DATA.spec[j][3]===kind),0);
$('stats').textContent=`Near-boundary probability ${(near*100).toFixed(2)}% · Proxy penetration ${(hit*100).toFixed(2)}% · Retained raw mass ${(z*100).toFixed(2)}% · Shown shape mass ${(mass*100).toFixed(2)}% (not renormalized)`;
const cloud={type:'scatter3d',mode:'markers',x:ids.map(j=>DATA.spec[j][0]),y:ids.map(j=>DATA.spec[j][1]),z:ids.map(j=>DATA.spec[j][2]),customdata:ids,text:ids.map(j=>`Cell ${j}, probability ${(100*q[j]).toFixed(3)}%, gap ${(100*DATA.gap[m][j]).toFixed(2)} cm`),hovertemplate:'%{text}<extra></extra>',marker:{size:ids.map(j=>3+15*Math.sqrt(q[j])),color:ids.map(j=>q[j]),colorscale:'Viridis',showscale:true,colorbar:{title:{text:'Probability'}}}};
const body={type:'scatter3d',mode:'markers',x:points.map(p=>p[0]),y:points.map(p=>p[1]),z:points.map(p=>p[2]),marker:{size:5,color:'#55d8c1'},hoverinfo:'skip'};
const root=DATA.motion[m].map(frame=>frame[0]);const path={type:'scatter3d',mode:'lines',x:root.map(p=>p[0]),y:root.map(p=>p[1]),z:root.map(p=>p[2]),line:{color:'#55d8c1',width:3},hoverinfo:'skip'};
await Plotly.react($('plot'),[cloud,body,path,obstacle()],{paper_bgcolor:'#111c2b',font:{color:'#dceafa'},margin:{l:0,r:0,t:0,b:0},showlegend:false,uirevision:'fixed',scene:{aspectmode:'data',xaxis:{title:{text:'x (m)'}},yaxis:{title:{text:'y (m)'}},zaxis:{title:{text:'z (m)'}}}},{responsive:true,displaylogo:false});
const s=DATA.spec[selected];$('detail').textContent=`Selected ${['beam','box','sphere'][s[3]]}, cell ${selected}, center (${s.slice(0,3).join(', ')}) m; probability ${(q[selected]*100).toFixed(4)}%; proxy gap ${(DATA.gap[m][selected]*100).toFixed(2)} cm. No physical label.`;
}finally{busy=false;}}
for(const id of ['motion','model','mode','kind'])$(id).onchange=draw;$('frame').oninput=draw;
$('sample').onclick=()=>{const{q}=state();let r=Math.random()*q.reduce((a,b)=>a+b,0);for(let j=0;j<q.length;j++){r-=q[j];if(r<=0){selected=j;break;}}$('kind').value=DATA.spec[selected][3];draw();};
$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';};setInterval(()=>{if(playing&&!busy){$('frame').value=(+$('frame').value+1)%32;draw();}},150);
draw().then(()=>{$('plot').on('plotly_click',e=>{if(e.points[0].curveNumber===0){selected=e.points[0].customdata;draw();}});window.VIEWER_READY=true;});
